function manualGroup(p,d,m){if(p.prepDays===1)return[{d,m}];const start=Math.floor(d/p.prepDays)*p.prepDays,end=Math.min(6,start+p.prepDays-1),out=[];if(m===0){const count=Math.min(2,end-start+1);for(let day=start;day<=end;day++)if((day-start)%count===(d-start)%count)out.push({d:day,m:0})}else{const parity=((d-start)+m-1)%2;for(let day=start;day<=end;day++)for(let meal=1;meal<3;meal++)if(((day-start)+meal-1)%2===parity)out.push({d:day,m:meal})}return out}
function manualSelection(p,d,m,id){const next=normalizeSettings(p);next.manualMeals={};p.meals.forEach((row,day)=>row.forEach((x,slot)=>next.manualMeals[day+'-'+slot]=x.id));manualGroup(p,d,m).forEach(o=>next.manualMeals[o.d+'-'+o.m]=id);next.menuMode='manual';// Only settings persist; the next plan is rebuilt from ingredient quantities.
for(const k of ['meals','basket','sessions','total','totalKcal','catalogSnapshot','budgetSearch'])delete next[k];return next}
function pickerChoices(p,d,m,query='',ingredients=[]){const options=eligible(p),slots=manualGroup(p,d,m);return options[m].filter(id=>slots.every(o=>options[o.m].includes(id))&&recipes[id].name.toLocaleLowerCase('ru').includes(query.trim().toLocaleLowerCase('ru'))&&ingredients.every(k=>recipes[id].ing[k]>0))}
function renderBuilder(){$('#screen').innerHTML=`<section class="enter"><div class="eyebrow">Вы — шеф этой недели</div><h1>Сегодня хочется…</h1><p class="intro">Выбирайте блюда, ищите по продуктам<br>или доверьтесь случаю.</p><div class="builder-actions"><button id="builder-random" class="primary">↻ Новая случайная неделя</button><button id="builder-budget" class="outline-button">Подобрать заново под бюджет</button></div><div class="builder-total"><span>${plan.menuMode==='manual'?'Моё меню':plan.menuMode==='free'?'Свободный подбор':'Подбор под бюджет'}</span><b>${rub(plan.total)}</b><small>Вся корзина · бюджет ${rub(plan.budget)}${plan.total>plan.budget?' · выше на '+rub(plan.total-plan.budget):''}</small></div><p class="note">Автоподбор заменяет всю неделю. При ручном выборе остальные блюда сохраняются. Аллергии, тип питания, калории и техника учитываются всегда.${plan.prepDays>1?' В режиме заготовок замена действует на все порции одной группы готовки.':''}</p>${plan.meals.map((row,d)=>`<section class="builder-day"><h2>${days[d]}</h2>${row.map((m,i)=>`<div class="builder-meal"><button class="builder-recipe" data-see="${d},${i}"><span class="dish-disc">${recipes[m.id].emoji}</span><span><small>${mealNames[i]}</small><b>${recipes[m.id].name}</b><small>${rub(m.cost)} · на семью</small></span></button><button class="round-add" data-choose="${d},${i}" aria-label="Выбрать блюдо: ${days[d]}, ${mealNames[i]}">↔</button></div>`).join('')}</section>`).join('')}<p class="note">Суммы у блюд — стоимость съеденных продуктов. Корзина выше учитывает целые упаковки. ${plan.priceMode==='real'?'Цены загруженных товаров.':'Цены демонстрационные.'}</p></section>`;document.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>openPicker(...b.dataset.choose.split(',').map(Number)));document.querySelectorAll('[data-see]').forEach(b=>b.onclick=()=>openRecipe(...b.dataset.see.split(',').map(Number)));function generateMode(mode){try{calculate({...state,menuMode:mode,manualMeals:{}},variant+1);renderBuilder();toast('Новая неделя готова')}catch(e){toast(e.message)}}$('#builder-random').onclick=()=>generateMode('free');$('#builder-budget').onclick=()=>generateMode('budget')}
function openPicker(d,m){const group=manualGroup(plan,d,m);$('#recipe-content').innerHTML=`<div class="eyebrow">${days[d]} · ${mealNames[m]}</div><h2>Что приготовим?</h2><p class="note">${group.length>1?'Заменим все порции: '+group.map(o=>short[o.d]+' · '+mealNames[o.m]).join(', '):'Выбирайте блюдо для этого приёма пищи.'}</p><label class="picker-label" for="recipe-search">Поиск по названию</label><input class="picker-input" id="recipe-search" type="search" placeholder="Например, суп или гречка"><details class="ingredient-filter"><summary>Подобрать по продуктам</summary><p class="note">Блюдо должно содержать все отмеченные продукты. Другие ингредиенты тоже могут понадобиться.</p><div class="allergy-grid">${Object.entries(products).map(([k,p])=>`<label><input type="checkbox" data-pick-ingredient="${k}">${p[0]}</label>`).join('')}</div></details><button id="random-recipe" class="primary">✦ Случайный из подходящих</button><p id="picker-status" role="status"></p><div id="picker-results"></div>`;let candidates=[];function apply(id){try{calculate(manualSelection(plan,d,m,id),variant);$('#recipe').close();view='builder';renderResult();toast('Блюдо заменено. Корзина пересчитана.')}catch(e){$('#picker-status').textContent=e.message}}
function draw(){const chosen=Array.from(document.querySelectorAll('[data-pick-ingredient]:checked'),x=>x.dataset.pickIngredient);candidates=pickerChoices(plan,d,m,$('#recipe-search').value,chosen);$('#picker-status').textContent=candidates.length?'Подходящих рецептов: '+candidates.length:'Нет подходящих блюд. Попробуйте другое название или меньше продуктов.';$('#random-recipe').disabled=!candidates.length;$('#picker-results').innerHTML=candidates.map(id=>{const r=recipes[id],factor=plan.totalKcal*shares[m]/kcal(r),cost=Object.entries(r.ing).reduce((n,[k,g])=>n+g*factor/products[k][1]*price(k,plan.stores).price,0);return`<article class="pick-card"><div class="pick-art" aria-hidden="true">${r.emoji}</div><h3>${r.name}</h3><p>${time(id,method(id,plan))} мин · ${rub(cost)} на семью</p><small>${Object.keys(r.ing).map(k=>products[k][0]).join(', ')}</small><details><summary>Как готовить</summary><ol>${r.steps.map(t=>`<li>${t}</li>`).join('')}</ol>${recipeSource(r)}</details><button class="primary" data-pick="${id}">${plan.meals[d][m].id===id?'Оставить это блюдо':'＋ В меню'}</button></article>`}).join('');document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>apply(Number(b.dataset.pick)))}$('#recipe-search').oninput=draw;document.querySelectorAll('[data-pick-ingredient]').forEach(b=>b.onchange=draw);$('#random-recipe').onclick=()=>{const other=candidates.filter(id=>id!==plan.meals[d][m].id),pool=other.length?other:candidates;if(pool.length)apply(pool[Math.floor(Math.random()*pool.length)])};draw();$('#recipe').showModal()}
